Test.test("TERMINATION: model that only tries SAME read is blocked by clause 4 on 2nd call", () => {
  let p = Guard.makePolicyWithDefaults({
    budget: 20,
    readDraftCap: 10,
    sameOpRetryCap: 1,
    deliverableSignal: null
  });
  let s = Guard.newGuardState(p);
  let call_args = Primitive_option.some(grepArgsDict("x", "src"));
  let call = {
    tool: "grep",
    args: call_args
  };
  let d1 = Guard.evaluateGuards(s, call, p);
  assertionIsTrue("first allowed", d1.allow);
  Guard.updateState(s, call, {
    ok: false
  }, p);
  let d2 = Guard.evaluateGuards(s, call, p);
  assertionIsFalse("second denied", d2.allow);
  assertionEqual("redundant_read", d2.guard, "redundant_read");
  let checkAllDenied = (_remaining, _soFar) => {
    while (true) {
      let soFar = _soFar;
      let remaining = _remaining;
      if (remaining <= 0 || !soFar) {
        return soFar;
      }
      let d = Guard.evaluateGuards(s, call, p);
      _soFar = soFar && !d.allow;
      _remaining = remaining - 1 | 0;
      continue;
    };
  };
  assertionIsTrue("all denied", checkAllDenied(10, true));
});

Test.test("TERMINATION: model that only tries DIFFERENT reads is blocked by clause 5 at readDraftCap", () => {
  let p = Guard.makePolicyWithDefaults({
    budget: 30,
    readDraftCap: 3,
    sameOpRetryCap: 10,
    deliverableSignal: null
  });
  let s = Guard.newGuardState(p);
  let loop = _idx => {
    while (true) {
      let idx = _idx;
      if (idx >= p.readDraftCap) {
        return;
      }
      let call_args = Primitive_option.some(grepArgsDict("unique" + idx.toString(), "src"));
      let call = {
        tool: "grep",
        args: call_args
      };
      let d = Guard.evaluateGuards(s, call, p);
      assertionIsTrue("allowed at i=" + idx.toString(), d.allow);
      Guard.updateState(s, call, {
        ok: false
      }, p);
      _idx = idx + 1 | 0;
      continue;
    };
  };
  loop(0);
  let after_args = Primitive_option.some(grepArgsDict("new", "src"));
  let after = {
    tool: "grep",
    args: after_args
  };
  let d = Guard.evaluateGuards(s, after, p);
  assertionIsFalse("read_budget triggered", d.allow);
  assertionEqual("read_budget guard", d.guard, "read_budget");
});

